package com.shipflow.tracking.api;
import com.shipflow.common.api.ApiResponse;import com.shipflow.order.application.ShipmentOrderException;import com.shipflow.tracking.api.model.*;import com.shipflow.tracking.application.TrackingQueryApplicationService;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/shipment-orders/{orderId}/tracking") public class TrackingQueryController{private final TrackingQueryApplicationService service;public TrackingQueryController(TrackingQueryApplicationService s){service=s;}@GetMapping public ApiResponse<List<TrackingEventResponse>> list(@PathVariable Long orderId,@AuthenticationPrincipal Jwt jwt){return ApiResponse.success(service.list(tenant(jwt),orderId));}@GetMapping("/status") public ApiResponse<TrackingStatusResponse> status(@PathVariable Long orderId,@AuthenticationPrincipal Jwt jwt){return ApiResponse.success(service.status(tenant(jwt),orderId));}private Long tenant(Jwt jwt){try{return jwt==null?null:Long.valueOf(jwt.getClaimAsString("tenant_id"));}catch(Exception e){throw new ShipmentOrderException("COMMON-1004",403);}}}
